package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TarArchiveOutputStream_putArchiveEntry_TriageGen1Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarArchiveOutputStream;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        tarArchiveOutputStream = new TarArchiveOutputStream(out);
    }

    @Test
    public void testPutArchiveEntry_LongFileModeGNU_File() throws IOException {
        // Setup
        tarArchiveOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_GNU);

        // Use a long name to trigger the GNU longlink logic
        String longName = "this_is_a_very_long_filename_that_exceeds_the_standard_tar_limit_of_100_characters_to_test_gnu_mode.txt";
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(10); // Set a size for the actual entry

        // Execute
        tarArchiveOutputStream.putArchiveEntry(entry);

        // Verify
        // Since we cannot easily inspect the internal buffer state of the private fields, 
        // we verify that no exception is thrown and the stream has received data.
        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_LongFileModeGNU_Directory() throws IOException {
        // Setup
        tarArchiveOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_GNU);
        String longName = "a_very_long_directory_name_that_should_trigger_the_long_link_logic_in_the_tar_stream_format.dir";
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        // TarArchiveEntry directory check is based on isDirectory()

        // Execute
        tarArchiveOutputStream.putArchiveEntry(entry);

        // Verify
        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_LongFileModeTruncate_NormalFile() throws IOException {
        // Setup
        tarArchiveOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_TRUNCATE);
        TarArchiveEntry entry = new TarArchiveEntry("normal.txt");
        entry.setSize(5);

        // Execute
        tarArchiveOutputStream.putArchiveEntry(entry);

        // Verify
        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_LongFileModeDefault_NormalFile() throws IOException {
        // Setup
        // Default mode is usually not LONGFILE_GNU or LONGFILE_TRUNCATE
        tarArchiveOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_DEFAULT);
        TarArchiveEntry entry = new TarArchiveEntry("small.txt");
        entry.setSize(5);

        // Execute
        tarArchiveOutputStream.putArchiveEntry(entry);

        // Verify
        Assert.assertTrue(out.size() > 0);
    }

    @Test(expected = RuntimeException.class)
    public void testPutArchiveEntry_ThrowsExceptionWhenTooLongAndNotGNU() throws IOException {
        // Setup
        // Use a mode that is neither GNU nor TRUNCATE
        tarArchiveOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_DEFAULT);

        // We need to simulate a long name. 
        // Note: The code checks the mode, not the actual length of the string, 
        // but the logic branches based on the mode variable.
        // To hit the RuntimeException branch, mode must NOT be GNU and NOT be TRUNCATE.

        TarArchiveEntry entry = mock(TarArchiveEntry.class);
        when(entry.getName()).thenReturn("a_very_long_name_that_is_not_handled_by_current_mode");
        when(entry.isDirectory()).thenReturn(false);
        // The code casts (TarArchiveEntry) archiveEntry, so we must use a real TarArchiveEntry 
        // or a mock that can be cast. Since we can't mock the cast easily if it's a hard cast, 
        // we use a real one.

        TarArchiveEntry realEntry = new TarArchiveEntry("long_name_triggering_exception");
        // To force the branch where it hits the RuntimeException, we ensure mode is DEFAULT
        tarArchiveOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_DEFAULT);

        // However, the code provided has a logic flaw/feature: it throws the exception 
        // regardless of actual length if the mode isn't GNU or TRUNCATE? 
        // Looking at the code: if (longFileMode == GNU) { ... } else if (longFileMode != TRUNCATE) { throw ... }
        // Actually, the code as written will ALWAYS throw if mode is DEFAULT, regardless of string length.

        tarArchiveOutputStream.putArchiveEntry(realEntry);
    }

    @Test
    public void testPutArchiveEntry_DirectoryLogic() throws IOException {
        // Setup
        tarArchiveOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_DEFAULT);
        TarArchiveEntry entry = new TarArchiveEntry("test_dir");
        // In TarArchiveEntry, a directory is indicated by its type
        // We can't easily set type without internal access, but TarArchiveEntry has constructor/methods
        // For this test, we assume the entry is a directory if we can manipulate it.

        // We'll use a spy to ensure isDirectory returns true
        TarArchiveEntry spyEntry = spy(new TarArchiveEntry("test_dir"));
        when(spyEntry.isDirectory()).thenReturn(true);
        when(spyEntry.getSize()).thenReturn(100L); // Should be ignored for directory

        // Execute
        tarArchiveOutputStream.putArchiveEntry(spyEntry);

        // Verify
        Assert.assertTrue(out.size() > 0);
    }
}
